    class LeaderAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Becoming a Leader`;
            this.version = `1.2.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // The concept's truth: the CEO threatened a provisional leadership identity, not the
            // task. Owning the miss is the only first move that does identity work.
            this.TRUE_THREAT = `identity`;
            this.TRUE_RESPONSE = `own`;

            // Company norm the recovery aims at; starting pulse after the setback.
            this.CONFIDENCE_NORM = 71;
            this.CONFIDENCE_START = 38;
            // The "held authentic" sweet spot on the 0..100 armour..disclosure spectrum.
            this.STANCE_LOW = 50;
            this.STANCE_HIGH = 70;
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    confidence: 38,
                    identity: 30,
                    credibility: 40,
                    sustain: 20,
                    relationships: [],
                    relationshipCount: 0,
                    daysSpent: 0,
                    secondLeadGone: false,
                    confidenceHistory: [38],
                    identityHistory: [30],
                    credibilityHistory: [40],
                    sustainHistory: [20],
                    coachMessages: [],
                    unheld: [],
                    moves: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    threat: `identity`,
                    response: `own`,
                    candor: 50,
                    relationships: [],
                    ask: `hold`,
                    stance: 30,
                    leads: `ownask`,
                    reveal: `measured`,
                    purpose: `specific`,
                    roadmap: `bridge`,
                    horizon: `visible`,
                    conviction: 50
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const thr = document.getElementById(`threatInput`);
                const resp = document.getElementById(`responseInput`);
                const can = document.getElementById(`candorInput`);
                if (thr) decisions.threat = thr.value;
                if (resp) decisions.response = resp.value;
                if (can) decisions.candor = parseInt(can.value, 10);
                if (!Number.isFinite(decisions.candor) || decisions.candor < 0 || decisions.candor > 100) {
                    warn(`warn_candor_range`); return false;
                }
            } else if (round === 2) {
                const ids = [
                    [`relPeer`, `peer`], [`relSponsor`, `sponsor`],
                    [`relReport`, `report`], [`relCoach`, `coach`]
                ];
                const picked = [];
                ids.forEach(([elId, val]) => {
                    const el = document.getElementById(elId);
                    if (el && el.checked) picked.push(val);
                });
                decisions.relationships = picked;
                const ask = document.getElementById(`askInput`);
                if (ask) decisions.ask = ask.value;
            } else if (round === 3) {
                const st = document.getElementById(`stanceInput`);
                const ld = document.getElementById(`leadsInput`);
                const rv = document.getElementById(`revealInput`);
                if (st) decisions.stance = parseInt(st.value, 10);
                if (ld) decisions.leads = ld.value;
                if (rv) decisions.reveal = rv.value;
                if (!Number.isFinite(decisions.stance) || decisions.stance < 0 || decisions.stance > 100) {
                    warn(`warn_stance_range`); return false;
                }
            } else if (round === 4) {
                const pp = document.getElementById(`purposeInput`);
                const rm = document.getElementById(`roadmapInput`);
                const hz = document.getElementById(`horizonInput`);
                const cv = document.getElementById(`convictionInput`);
                if (pp) decisions.purpose = pp.value;
                if (rm) decisions.roadmap = rm.value;
                if (hz) decisions.horizon = hz.value;
                if (cv) decisions.conviction = parseInt(cv.value, 10);
                if (!Number.isFinite(decisions.conviction) || decisions.conviction < 0 || decisions.conviction > 100) {
                    warn(`warn_conviction_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            let confDelta = 0, idDelta = 0, credDelta = 0, sustDelta = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;
            if (!ds.unheld) ds.unheld = [];
            if (!ds.moves) ds.moves = [];
            const tags = [];
            let held = false;

            if (round === 1) {
                // Diagnose the threat. Reading it as identity work (not a slide problem) is the
                // whole point; owning the miss is the only first move that builds rather than
                // erodes. Common Error 1: fixing the slides, not the self.
                if (d.threat === this.TRUE_THREAT) { idDelta += 16; credDelta += 4; coachKey = `coach_r1_threat_right`; }
                else if (d.threat === `task`) { idDelta -= 8; confDelta -= 2; coachKey = `coach_r1_threat_task`; tags.push('task'); }
                else { idDelta -= 4; coachKey = `coach_r1_threat_off`; tags.push('misread'); }
                if (d.response !== this.TRUE_RESPONSE) tags.push('first');

                switch (d.response) {
                    case `own`:
                        confDelta += 8; credDelta += 10; idDelta += 6; sustDelta += 6;
                        coachKey = (d.threat === this.TRUE_THREAT) ? `coach_r1_own_sharp` : `coach_r1_own`; break;
                    case `defend`:
                        confDelta -= 4; credDelta -= 8; idDelta -= 2; coachKey = `coach_r1_defend`; break;
                    case `deflect`:
                        confDelta -= 6; credDelta -= 10; coachKey = `coach_r1_deflect`; break;
                    case `withdraw`:
                        confDelta -= 10; credDelta -= 6; idDelta -= 8; sustDelta -= 6;
                        ds.secondLeadGone = true; coachKey = `coach_r1_withdraw`; break;
                }

                // Candor = willingness to do identity work rather than hide in the spreadsheet.
                if (d.candor >= 60) { idDelta += 8; sustDelta += 4; }
                else if (d.candor <= 25) { idDelta -= 8; sustDelta -= 4; coachKey = `coach_r1_lowcandor`; }

                held = (d.threat === this.TRUE_THREAT && d.response === this.TRUE_RESPONSE);
                summaryKey = held ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Build a holding environment. Selectivity is the lesson: one or two who can
                // actually hold this. Common Error 4 (diffuse leaning) and the solo-heroics trap.
                const rels = d.relationships || [];
                ds.relationships = rels.slice();
                ds.relationshipCount = rels.length;
                // Roughly two days of trust/time per relationship genuinely opened.
                ds.daysSpent = rels.length * 2;

                const REL_ID = { peer: 6, sponsor: 4, report: 7, coach: 8 };
                const REL_CRED = { peer: 2, sponsor: 9, report: 5, coach: 3 };
                const REL_SUST = { peer: 7, sponsor: 2, report: 6, coach: 9 };
                let relId = 0, relCred = 0, relSust = 0;
                rels.forEach((r) => {
                    relId += (REL_ID[r] || 0);
                    relCred += (REL_CRED[r] || 0);
                    relSust += (REL_SUST[r] || 0);
                });
                const diffuse = rels.length >= 3;
                if (diffuse) {
                    // Diffuse leaning: nobody is opened up to fully, so each relationship gives half,
                    // and the exhaustion costs identity and sustainability.
                    idDelta += Math.round(relId / 2) - 6;
                    credDelta += Math.round(relCred / 2);
                    sustDelta += Math.round(relSust / 2) - 8;
                    tags.push('diffuse');
                } else {
                    idDelta += relId; credDelta += relCred; sustDelta += relSust;
                }

                if (diffuse) {
                    coachKey = 'coach_r2_diffuse';
                } else if (rels.length === 0) {
                    tags.push('solo');
                    // Playable since v1.2.0: going it alone is one of the mistakes of this round.
                    idDelta -= 12; sustDelta -= 12; coachKey = `coach_r2_solo`;
                } else if (rels.length === 1) {
                    idDelta += 6; sustDelta += 4; coachKey = `coach_r2_one`;
                } else if (rels.length === 2) {
                    idDelta += 10; sustDelta += 8; credDelta += 3; coachKey = `coach_r2_two`;
                }

                // Leaning ONLY on the sponsor clings to the old expert identity (provisional-selves trap).
                if (rels.length === 1 && rels[0] === `sponsor`) {
                    idDelta -= 6; sustDelta -= 4; coachKey = `coach_r2_sponsoronly`; tags.push('sponsor');
                }
                // A holding environment that includes a peer or coach gives real containment.
                const hasHolder = rels.indexOf(`peer`) !== -1 || rels.indexOf(`coach`) !== -1;
                if (!hasHolder && rels.length > 0 && !diffuse) { sustDelta -= 4; }

                // The ask matters: being HELD (vs reassured/rescued) is the developmental move.
                // With nobody chosen there is nobody to ask.
                const soloKey = coachKey;
                if (rels.length > 0 && d.ask !== 'hold') tags.push('ask');
                switch (rels.length > 0 ? d.ask : '') {
                    case `hold`:
                        idDelta += 8; sustDelta += 8; confDelta += 4; coachKey = `coach_r2_ask_hold`; break;
                    case `advice`:
                        credDelta += 4; idDelta += 2; coachKey = `coach_r2_ask_advice`; break;
                    case `reassure`:
                        idDelta -= 4; sustDelta -= 4; coachKey = `coach_r2_ask_reassure`; break;
                    case `rescue`:
                        credDelta -= 8; idDelta -= 6; coachKey = `coach_r2_ask_rescue`; break;
                }

                if (rels.length === 0) coachKey = soloKey;
                if (diffuse) coachKey = 'coach_r2_diffuse';
                held = (rels.length >= 1 && rels.length <= 2 && d.ask === `hold` && hasHolder);
                summaryKey = held ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Take a stance. Armour (low) = false certainty the room sees through; collapse
                // (high) = contagious doubt. The held authentic band is ~50-70. Common Errors 2 & 3.
                const s = d.stance;
                if (s < this.STANCE_LOW) {
                    // Armouring up.
                    const dist = this.STANCE_LOW - s;
                    confDelta -= Math.round(dist / 5) + 2;
                    credDelta -= Math.round(dist / 6) + 2;
                    idDelta -= 4; sustDelta -= 6;
                    coachKey = `coach_r3_armour`;
                } else if (s > this.STANCE_HIGH) {
                    // Collapsing into disclosure — contagion.
                    const dist = s - this.STANCE_HIGH;
                    confDelta -= Math.round(dist / 4) + 3;
                    credDelta -= Math.round(dist / 8);
                    idDelta -= 2; sustDelta -= 2;
                    coachKey = `coach_r3_collapse`;
                } else {
                    // Held authentic stance: congruence between values, identity and action.
                    confDelta += 12; credDelta += 8; idDelta += 10; sustDelta += 10;
                    coachKey = `coach_r3_held`;
                }

                // The opening line to the two departing leads.
                switch (d.leads) {
                    case `ownask`:
                        confDelta += 8; credDelta += 8; idDelta += 6; sustDelta += 4;
                        coachKey = (s >= this.STANCE_LOW && s <= this.STANCE_HIGH) ? `coach_r3_ownask_sharp` : coachKey; break;
                    case `command`:
                        confDelta -= 8; credDelta -= 10; sustDelta -= 6;
                        ds.secondLeadGone = true; coachKey = `coach_r3_command`; break;
                    case `confess`:
                        confDelta -= 12; idDelta -= 4; sustDelta -= 4;
                        coachKey = `coach_r3_confess`; break;
                    case `transactional`:
                        credDelta -= 12; sustDelta -= 8; idDelta -= 4;
                        coachKey = `coach_r3_transactional`; break;
                }

                // What she reveals about her own doubt.
                if (d.reveal === `measured`) { idDelta += 8; sustDelta += 6; confDelta += 4; }
                else if (d.reveal === `none`) { idDelta -= 6; sustDelta -= 8; credDelta += 2; coachKey = (s < this.STANCE_LOW) ? coachKey : `coach_r3_reveal_none`; }
                else if (d.reveal === `all`) { confDelta -= 8; sustDelta -= 4; coachKey = (s > this.STANCE_HIGH) ? coachKey : `coach_r3_reveal_all`; }

                if (s < this.STANCE_LOW || d.leads === 'command' || d.reveal === 'none') tags.push('armour');
                if (s > this.STANCE_HIGH || d.leads === 'confess' || d.reveal === 'all') tags.push('over');
                if (d.leads === 'transactional') tags.push('trans');
                held = (s >= this.STANCE_LOW && s <= this.STANCE_HIGH && d.leads === `ownask` && d.reveal === `measured`);
                summaryKey = held ? `sum_r3_good` : `sum_r3_weak`;
            } else if (round === 4) {
                // Set the purpose. A specific, honest purpose survives the next setback; a slogan
                // gives no guidance. Common Error 5. The roadmap reframe and recovery plan land
                // the transformation. Conviction that a held identity (not performed certainty)
                // is leadership nudges sustainability.
                // The three choices compound: purpose, roadmap and recovery plan count in full only
                // when they line up. Otherwise the positive parts count for half.
                held = (d.purpose === `specific` && d.roadmap === `bridge` && d.horizon === `visible`);
                const pos = [0, 0, 0, 0], neg = [0, 0, 0, 0];
                const add = function(c, i, cr, su) {
                    [c, i, cr, su].forEach(function(v, k) { if (v > 0) pos[k] += v; else neg[k] += v; });
                };
                switch (d.purpose) {
                    case `specific`: add(6, 12, 6, 18); coachKey = `coach_r4_specific`; break;
                    case `slogan`: add(0, -2, 0, -10); coachKey = `coach_r4_slogan`; tags.push('slogan'); break;
                    case `expert`: add(0, -8, -4, -6); coachKey = `coach_r4_expert`; tags.push('purpose'); break;
                    case `results`: add(0, -4, 0, -8); coachKey = `coach_r4_results`; tags.push('purpose'); break;
                }

                switch (d.roadmap) {
                    case `bridge`: add(8, 0, 12, 4); coachKey = (d.purpose === `specific`) ? `coach_r4_bridge_sharp` : `coach_r4_bridge`; break;
                    case `polish`: add(-4, 0, -6, 0); coachKey = `coach_r4_polish`; tags.push('roadmap'); break;
                    case `capitulate`: add(0, -10, 2, -8); coachKey = `coach_r4_capitulate`; tags.push('roadmap'); break;
                }

                switch (d.horizon) {
                    case `visible`: add(12, 0, 4, 6); break;
                    case `grand`: add(2, 0, 0, -6); coachKey = (d.purpose === `slogan`) ? coachKey : `coach_r4_grand`; tags.push('sequence'); break;
                    case `quiet`: add(-6, 0, 0, -4); coachKey = `coach_r4_quiet`; tags.push('sequence'); break;
                }
                const f4 = held ? 1 : 0.5;
                confDelta += Math.round(pos[0] * f4) + neg[0];
                idDelta += Math.round(pos[1] * f4) + neg[1];
                credDelta += Math.round(pos[2] * f4) + neg[2];
                sustDelta += Math.round(pos[3] * f4) + neg[3];

                // Conviction that a held, honest identity (not armour) is leadership.
                sustDelta += Math.round((d.conviction - 60) / 8);

                summaryKey = held ? `sum_r4_good` : `sum_r4_weak`;
            }

            // A second team lead leaving costs confidence (~25 of 240 destabilised).
            if (ds.secondLeadGone && round <= 3) {
                confDelta -= 4;
            }

            // Carry: the room grants gains cumulatively. Each earlier round that did not hold
            // discounts the gains of this round by a quarter (floor: one quarter of their weight).
            const earlier = ds.unheld.filter(function(r) { return r < round; }).length;
            if (earlier > 0) {
                const fac = Math.max(0.25, 1 - 0.25 * earlier);
                if (confDelta > 0) confDelta = Math.round(confDelta * fac);
                if (idDelta > 0) idDelta = Math.round(idDelta * fac);
                if (credDelta > 0) credDelta = Math.round(credDelta * fac);
                if (sustDelta > 0) sustDelta = Math.round(sustDelta * fac);
            }
            ds.unheld = ds.unheld.filter(function(r) { return r < round; });
            if (!held) ds.unheld.push(round);
            ds.moves = ds.moves.filter(function(m) { return m && m.r < round; });
            ds.moves.push({ r: round, held: held, tags: tags });

            // Apply deltas with clamps. Confidence is a percentage toward the 71% norm.
            ds.confidence = Math.max(0, Math.min(100, ds.confidence + confDelta));
            ds.identity = Math.max(0, Math.min(100, ds.identity + idDelta));
            ds.credibility = Math.max(0, Math.min(100, ds.credibility + credDelta));
            ds.sustain = Math.max(0, Math.min(100, ds.sustain + sustDelta));

            ds.confidenceHistory.push(Math.round(ds.confidence));
            ds.identityHistory.push(Math.round(ds.identity));
            ds.credibilityHistory.push(Math.round(ds.credibility));
            ds.sustainHistory.push(Math.round(ds.sustain));

            let coachMsg = window.mySimulation.t(coachKey);
            if (round === 4 && !held) coachMsg += '<br><span class="leadersim-carry">' + window.mySimulation.t('r4_compound_note') + '</span>';
            if (earlier > 0) coachMsg += '<br><span class="leadersim-carry">' + window.mySimulation.t('carry_note_' + Math.min(3, earlier)) + '</span>';
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(((__eqilNext) => function() {
                self._updateBriefing({ currentPeriod: __eqilNext });
            })(state.currentPeriod + 1), 500);

            var res = {
                period: state.currentPeriod,
                confidence: Math.round(ds.confidence),
                confidenceDelta: Math.round(confDelta),
                identity: Math.round(ds.identity),
                identityDelta: Math.round(idDelta),
                credibility: Math.round(ds.credibility),
                credibilityDelta: Math.round(credDelta),
                sustain: Math.round(ds.sustain),
                sustainDelta: Math.round(sustDelta),
                secondLeadGone: ds.secondLeadGone,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
            // Expose composite to the reporting/grading layer each period (results_utils.php reads
            // domainState.performance.overallScore); period 4 locks the authoritative score.
            ds.performance = { overallScore: this._composite(ds) };
            return res;
        }

        setupUI(uiManager) {
            uiManager.bind(`currentDay`, `currentPeriod`);
            uiManager.bind(`maxPeriods`, `maxPeriods`);
            uiManager.bind(`identityDisplay`, `domainState.identity`, (v) => Math.round(v));
            uiManager.bind(`credibilityDisplay`, `domainState.credibility`, (v) => Math.round(v));
            uiManager.bind(`sustainDisplay`, `domainState.sustain`, (v) => Math.round(v));
            uiManager.bind(`confidenceDisplay`, `domainState.confidence`, (v) => {
                const card = document.querySelector(`.leadersim-card-confidence`);
                const n = Number(v);
                if (card) {
                    card.classList.toggle(`leadersim-conf-low`, n < 45);
                    card.classList.toggle(`leadersim-conf-mid`, n >= 45 && n < 65);
                    card.classList.toggle(`leadersim-conf-high`, n >= 65);
                }
                return Math.round(n) + `%`;
            });
            uiManager.bind(`trustDisplay`, `domainState.daysSpent`, (v) => {
                const ds = window.mySimulation.state.domainState;
                const count = ds.relationshipCount || 0;
                const dayWord = window.mySimulation.t(`unit_days`);
                const relWord = window.mySimulation.t(count === 1 ? `unit_relationship` : `unit_relationships`);
                return Number(v) + ` ` + dayWord + ` · ` + count + ` ` + relWord;
            });

            const self = this;
            const can = document.getElementById(`candorInput`);
            const canReadout = document.getElementById(`candorReadout`);
            if (can && canReadout) {
                canReadout.textContent = can.value;
                can.addEventListener(`input`, function() { canReadout.textContent = can.value; });
            }
            const st = document.getElementById(`stanceInput`);
            const stReadout = document.getElementById(`stanceReadout`);
            if (st && stReadout) {
                stReadout.textContent = st.value;
                st.addEventListener(`input`, function() { stReadout.textContent = st.value; });
            }

            // Soft guard: limit relationship picks to two in the UI.
            const relIds = [`relPeer`, `relSponsor`, `relReport`, `relCoach`];
            const enforce = function() {
                let checked = 0;
                relIds.forEach((id) => { const el = document.getElementById(id); if (el && el.checked) checked++; });
                const trustEl = document.querySelector(`.leadersim-trust-bar`);
                if (trustEl) trustEl.classList.toggle(`leadersim-over`, checked > 2);
            };
            relIds.forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`change`, enforce);
            });
            enforce();
        }

        getChartConfig() {
            return {
                leaderChart: {
                    type: `line`,
                    data: {
                        labels: [],
                        datasets: [
                            {
                                label: `Team Confidence %`,
                                data: [],
                                borderColor: `#2f80c0`,
                                backgroundColor: `rgba(47,128,192,0.15)`,
                                borderWidth: 3,
                                fill: true,
                                tension: 0.25,
                                pointRadius: 5,
                                pointBackgroundColor: `#2f80c0`,
                                yAxisID: `y`
                            },
                            {
                                label: `Identity Integration`,
                                data: [],
                                borderColor: `#7a5cc4`,
                                backgroundColor: `rgba(122,92,196,0.08)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#7a5cc4`,
                                yAxisID: `y`
                            },
                            {
                                label: `Credibility`,
                                data: [],
                                borderColor: `#c98a16`,
                                backgroundColor: `rgba(201,138,22,0.08)`,
                                borderWidth: 2,
                                borderDash: [5, 4],
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#c98a16`,
                                yAxisID: `y`
                            },
                            {
                                label: `Sustainability`,
                                data: [],
                                borderColor: `#2e9e63`,
                                backgroundColor: `rgba(46,158,99,0.08)`,
                                borderWidth: 2,
                                fill: false,
                                tension: 0.25,
                                pointRadius: 4,
                                pointBackgroundColor: `#2e9e63`,
                                yAxisID: `y`
                            }
                        ]
                    },
                    options: {
                        responsive: true,
                        maintainAspectRatio: false,
                        plugins: {
                            legend: { position: `bottom`, labels: { color: `#2f3a55`, boxWidth: 14 } },
                            title: { display: false }
                        },
                        scales: {
                            y: {
                                beginAtZero: true, max: 100, position: `left`,
                                ticks: { color: `#61708f` }, grid: { color: `rgba(27,37,64,0.08)` },
                                title: { display: true, text: `0–100 (confidence in %)`, color: `#61708f` }
                            },
                            x: {
                                ticks: { color: `#61708f` }, grid: { color: `rgba(27,37,64,0.06)` },
                                title: { display: true, text: `Round`, color: `#61708f` }
                            }
                        }
                    }
                }
            };
        }

        getChartData(state) {
            const ds = state.domainState;
            const labels = ds.confidenceHistory.map((_, i) => (i === 0 ? `Start` : `R` + i));
            return {
                leaderChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.confidenceHistory },
                        { data: ds.identityHistory },
                        { data: ds.credibilityHistory },
                        { data: ds.sustainHistory }
                    ]
                }
            };
        }

        // Shared composite (0-100). Single source of truth for the per-period score written to
        // domainState.performance.overallScore (reporting/grading layer) AND the debrief. Weights
        // identical to v1.0.0.
        _composite(ds) {
            var confidence = Math.round(ds.confidence || 0), identity = Math.round(ds.identity || 0);
            var credibility = Math.round(ds.credibility || 0), sustain = Math.round(ds.sustain || 0);
            return Math.max(0, Math.min(100, Math.round(confidence * 0.3 + identity * 0.25 + credibility * 0.2 + sustain * 0.25)));
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const confidence = Math.round(ds.confidence);
            const identity = Math.round(ds.identity);
            const credibility = Math.round(ds.credibility);
            const sustain = Math.round(ds.sustain);

            // The mandate: recover confidence toward the 71% norm AND hold a sustainable,
            // integrated leadership identity (not performed authority).
            const recovered = confidence >= 65;
            const integrated = identity >= 60 && sustain >= 60;
            const composite = this._composite(ds);

            const T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };

            // Grade band: one function of the composite (v1.2.0). The KPI profile is told by the
            // insights and the badge, never by a second set of gates.
            let performanceKey = `grade_impostor`;
            if (composite >= 95) performanceKey = `grade_becoming`;
            else if (composite >= 75) performanceKey = `grade_recovery`;
            else if (composite >= 48) performanceKey = `grade_surface`;
            else if (composite >= 20) performanceKey = `grade_performed`;
            const performance = T(performanceKey);

            // Insights come from what this run did, round by round.
            const moves = (ds.moves || []).slice().sort(function(a, b) { return a.r - b.r; });
            const unheldRounds = moves.filter(function(m) { return !m.held; });
            const heldCount = moves.filter(function(m) { return m.held; }).length;
            const insights = [];
            if (unheldRounds.length === 0) insights.push(T('db_allheld'));
            else insights.push(T('db_turn_r' + unheldRounds[0].r));
            const named = [];
            unheldRounds.forEach(function(m) { if (m.tags && m.tags.length) named.push('db_' + m.tags[0]); });
            unheldRounds.forEach(function(m) { (m.tags || []).slice(1).forEach(function(tg) { named.push('db_' + tg); }); });
            named.slice(0, 3).forEach(function(k) { insights.push(T(k)); });
            if (composite >= 95) { insights.push(T(`insight_becoming`)); insights.push(T(`insight_held`)); }
            else if (ds.secondLeadGone) insights.push(T(`insight_leadgone`));
            else if (unheldRounds.length > 0 && insights.length < 3 && composite < 75) insights.push(T(`insight_partial`));
            const processScore = Math.round(100 * heldCount / 4);

            return {
                confidence: confidence,
                identity: identity,
                credibility: credibility,
                sustain: sustain,
                recovered: recovered,
                integrated: integrated,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                performanceKey: performanceKey,
                performance: performance,
                performanceLabel: performance,
                outcomeScore: composite,
                processScore: processScore,
                roundsHeld: heldCount,
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var T = (window.mySimulation && typeof window.mySimulation.t === 'function')
                ? function(k, v) { return window.mySimulation.t(k, v); }
                : function(k) { return k; };
            var s = summary || {};
            var score = (typeof s.totalScore === 'number') ? s.totalScore
                : (typeof s.composite === 'number' ? s.composite : 0);
            var grade = s.performance || (s.performanceKey ? T(s.performanceKey) : '');
            var rec = !!s.recovered;
            var badge = rec
                ? '<span class="bl-cm-badge bl-cm-yes">' + T('cm_recovered') + '</span>'
                : '<span class="bl-cm-badge bl-cm-no">' + T('cm_notrecovered') + '</span>';
            var insights = Array.isArray(s.insights) ? s.insights : [];
            var items = insights.map(function(t) { return '<li>' + t + '</li>'; }).join('');
            var metrics = ''
                + '<div class="bl-cm-metric"><span class="bl-cm-mv">' + Math.round(s.confidence||0) + '</span><span class="bl-cm-ml">' + T('cm_m_conf') + '</span></div>'
                + '<div class="bl-cm-metric"><span class="bl-cm-mv">' + Math.round(s.identity||0) + '</span><span class="bl-cm-ml">' + T('cm_m_identity') + '</span></div>'
                + '<div class="bl-cm-metric"><span class="bl-cm-mv">' + Math.round(s.credibility||0) + '</span><span class="bl-cm-ml">' + T('cm_m_cred') + '</span></div>'
                + '<div class="bl-cm-metric"><span class="bl-cm-mv">' + Math.round(s.sustain||0) + '</span><span class="bl-cm-ml">' + T('cm_m_sustain') + '</span></div>';
            return ''
                + '<div class="bl-completion">'
                +   '<div class="bl-cm-head">'
                +     '<div class="bl-cm-score">' + score + '<span class="bl-cm-score-max">/100</span></div>'
                +     '<div class="bl-cm-grade">' + grade + ' ' + badge + '</div>'
                +   '</div>'
                +   '<div class="bl-cm-metrics">' + metrics + '</div>'
                +   '<div class="bl-cm-insights-title">' + T('cm_debrief') + '</div>'
                +   '<ul class="bl-cm-insights">' + items + '</ul>'
                +   '<div class="bl-cm-sub"><span>' + T('db_outcome') + '</span> <span>' + score + '/100</span> <span>(' + T('db_outcome_sub') + ')</span> · <span>' + T('db_process') + '</span> <span>' + Math.round(s.processScore || 0) + '/100</span> <span>(' + Math.round(s.roundsHeld || 0) + '/4</span> <span>' + T('db_rounds_held') + ')</span></div>'
                +   '<div class="bl-cm-insights-title">' + T('cm_questions') + '</div>'
                +   '<ol class="bl-cm-questions"><li>' + T('cm_q1') + '</li><li>' + T('cm_q2') + '</li><li>' + T('cm_q3') + '</li></ol>'
                + '</div>';
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.confidence < 35) return window.mySimulation.t(`hint_confidence`);
            if (ds.sustain < 30 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_sustain`);
            if (ds.identity < 35 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_identity`);
            if (ds.relationshipCount === 0 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_solo`);
            if (ds.confidence >= 60 && ds.identity >= 55 && ds.sustain >= 55) return window.mySimulation.t(`hint_strong`);
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: `period`, label: `Round`, i18nKey: `col_round` },
                { key: `results.summary`, label: `Move`, i18nKey: `col_move` },
                { key: `results.confidence`, label: `Conf`, i18nKey: `col_confidence`, formatter: (v) => Math.round(v) + `%` },
                { key: `results.identity`, label: `Identity`, i18nKey: `col_identity`, formatter: (v) => Math.round(v) },
                { key: `results.credibility`, label: `Cred`, i18nKey: `col_credibility`, formatter: (v) => Math.round(v) },
                { key: `results.sustain`, label: `Sustain`, i18nKey: `col_sustain`, formatter: (v) => Math.round(v) }
            ];
        }

        getPresets() { return null; }

        _updateBriefing(state) {
            const idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            const round = this.ROUNDS[idx];
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;

            const titleEl = document.getElementById(`briefingTitle`);
            if (titleEl) titleEl.textContent = t(round.titleKey);
            const textEl = document.getElementById(`briefingText`);
            if (textEl) textEl.innerHTML = t(round.textKey);
            const nameEl = document.getElementById(`roundNameDisplay`);
            if (nameEl) nameEl.textContent = t(round.nameKey);
            const clockEl = document.getElementById(`clockDisplay`);
            if (clockEl) clockEl.textContent = t(round.clockKey);
            const chartEl = document.getElementById('leaderChart');
            if (chartEl) chartEl.setAttribute('aria-label', t('chart_alt'));

            for (let i = 0; i < this.ROUNDS.length; i++) {
                const panel = document.getElementById(this.ROUNDS[i].panelId);
                if (panel) panel.style.display = (i === idx) ? `block` : `none`;
            }
        }

